    admitToPolicy(step.items);
    policies.set(stepIndex, openPolicy(step.items));
    const contractOrdinal = contractOrdinalAfterOpening(contractsOpened);
    contractsOpened += 1;
    return {
      premium: quotePremium(step.items, scenario.customer, contractOrdinal),
    };
  });'''
